import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 8.2
.target sm_89
.address_size 64
.visible .entry triu_matmul(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N
)
{
    .reg .pred %p<16>;
    .reg .s32  %r<64>;
    .reg .s64  %rd<20>;
    .reg .f32  %f<16>;
    .shared .align 4 .f32 smA[272];
    .shared .align 4 .f32 smB[272];
    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1,  [N];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    mov.u32 %r2, %tid.x;      // tx (0..15)
    mov.u32 %r3, %tid.y;      // ty (0..7)
    mov.u32 %r4, %ctaid.x;    // bx
    mov.u32 %r5, %ctaid.y;    // by
    mul.lo.s32 %r6, %r4, 16;  // colBase
    mul.lo.s32 %r7, %r5, 16;  // rowBase
    add.s32 %r8, %r6, %r2;    // col
    add.s32 %r9, %r7, %r3;    // row0 = rowBase+ty
    add.s32 %r10, %r9, 8;     // row1 = row0+8
    setp.ge.s32 %p1, %r8, %r1;   // col>=N
    @%p1 bra DONE;
    setp.ge.s32 %p2, %r9, %r1;   // row0>=N
    setp.ge.s32 %p3, %r10, %r1;  // row1>=N
    not.pred %p7, %p2;           // row0 valid
    not.pred %p9, %p3;           // row1 valid
    mul.lo.s32 %r11, %r9, %r1;   // row0*N
    add.s32 %r12, %r11, %r8;
    mul.wide.s32 %rd4, %r12, 4;
    add.s64 %rd5, %rd3, %rd4;    // &C[row0][col]
    mul.lo.s32 %r13, %r10, %r1;  // row1*N
    add.s32 %r14, %r13, %r8;
    mul.wide.s32 %rd6, %r14, 4;
    add.s64 %rd7, %rd3, %rd6;    // &C[row1][col]
    setp.gt.s32 %p4, %r5, %r4;   // by > bx -> block fully below diagonal
    @%p4 bra STORE_ZERO;
    // precompute shared-memory offsets (invariant per thread across kt loop)
    mul.lo.s32 %r15, %r3, 17;    // baseA0/B0 = ty*17
    add.s32 %r16, %r15, 136;     // baseA1/B1 = (ty+8)*17
    add.s32 %r17, %r15, %r2;     // store idx0 = ty*17+tx
    add.s32 %r18, %r16, %r2;     // store idx1 = (ty+8)*17+tx
    // k-tile loop bounds: kt from by to bx inclusive
    mov.s32 %r19, %r5;    // kt = by
    mov.f32 %f1, 0f00000000;   // accumulator row0
    mov.f32 %f2, 0f00000000;   // accumulator row1
KT_LOOP:
    setp.gt.s32 %p5, %r19, %r4;   // kt > bx -> done
    @%p5 bra STORE_SUM;
    mul.lo.s32 %r20, %r19, 16;    // kBase
    add.s32 %r21, %r20, %r2;      // aCol = kBase+tx
    setp.lt.s32 %p6, %r21, %r1;   // aCol<N
    and.pred %p8, %p6, %p7;       // do A0 load (row0 valid & aCol valid)
    and.pred %p10, %p6, %p9;      // do A1 load (row1 valid & aCol valid)
    // ---- load A tile row0 element: A[row0][kBase+tx] ----
    mov.f32 %f3, 0f00000000;
    @!%p8 bra A0_LOAD_DONE;
    add.s32 %r22, %r11, %r21;     // row0*N + aCol
    mul.wide.s32 %rd8, %r22, 4;
    add.s64 %rd9, %rd1, %rd8;
    ld.global.f32 %f3, [%rd9];
A0_LOAD_DONE:
    mul.lo.s32 %r23, %r17, 4;
    mov.u32 %r24, smA;
    add.s32 %r25, %r24, %r23;
    st.shared.f32 [%r25], %f3;
    // ---- load A tile row1 element: A[row1][kBase+tx] ----
    mov.f32 %f4, 0f00000000;
    @!%p10 bra A1_LOAD_DONE;
    add.s32 %r26, %r13, %r21;     // row1*N + aCol
    mul.wide.s32 %rd10, %r26, 4;
    add.s64 %rd11, %rd1, %rd10;
    ld.global.f32 %f4, [%rd11];
A1_LOAD_DONE:
    mul.lo.s32 %r27, %r18, 4;
    mov.u32 %r28, smA;
    add.s32 %r29, %r28, %r27;
    st.shared.f32 [%r29], %f4;
    // ---- load B tile element for ty: B[kBase+ty][col] ----
    add.s32 %r30, %r20, %r3;      // bRow0 = kBase+ty
    setp.lt.s32 %p11, %r30, %r1;  // bRow0<N
    mov.f32 %f5, 0f00000000;
    @!%p11 bra B0_LOAD_DONE;
    mul.lo.s32 %r31, %r30, %r1;   // bRow0*N
    add.s32 %r32, %r31, %r8;      // + col
    mul.wide.s32 %rd12, %r32, 4;
    add.s64 %rd13, %rd2, %rd12;
    ld.global.f32 %f5, [%rd13];
B0_LOAD_DONE:
    mul.lo.s32 %r33, %r17, 4;
    mov.u32 %r34, smB;
    add.s32 %r35, %r34, %r33;
    st.shared.f32 [%r35], %f5;
    // ---- load B tile element for ty+8: B[kBase+ty+8][col] ----
    add.s32 %r36, %r30, 8;        // bRow1 = kBase+ty+8
    setp.lt.s32 %p12, %r36, %r1;  // bRow1<N
    mov.f32 %f6, 0f00000000;
    @!%p12 bra B1_LOAD_DONE;
    mul.lo.s32 %r37, %r36, %r1;   // bRow1*N
    add.s32 %r38, %r37, %r8;      // + col
    mul.wide.s32 %rd14, %r38, 4;
    add.s64 %rd15, %rd2, %rd14;
    ld.global.f32 %f6, [%rd15];
B1_LOAD_DONE:
    mul.lo.s32 %r39, %r18, 4;
    mov.u32 %r40, smB;
    add.s32 %r41, %r40, %r39;
    st.shared.f32 [%r41], %f6;
    bar.sync 0;
    // compute partial sums over 16 k values, two output rows per thread
    mov.s32 %r42, 0;               // kk
COMPUTE_LOOP:
    setp.ge.s32 %p13, %r42, 16;
    @%p13 bra COMPUTE_DONE;
    add.s32 %r43, %r15, %r42;      // smA row0 index = ty*17+kk
    mul.lo.s32 %r44, %r43, 4;
    mov.u32 %r45, smA;
    add.s32 %r46, %r45, %r44;
    ld.shared.f32 %f7, [%r46];
    add.s32 %r47, %r16, %r42;      // smA row1 index = (ty+8)*17+kk
    mul.lo.s32 %r48, %r47, 4;
    add.s32 %r49, %r45, %r48;
    ld.shared.f32 %f8, [%r49];
    mad.lo.s32 %r50, %r42, 17, %r2;  // smB index = kk*17+tx
    mul.lo.s32 %r51, %r50, 4;
    mov.u32 %r52, smB;
    add.s32 %r53, %r52, %r51;
    ld.shared.f32 %f9, [%r53];
    fma.rn.f32 %f1, %f7, %f9, %f1;
    fma.rn.f32 %f2, %f8, %f9, %f2;
    add.s32 %r42, %r42, 1;
    bra.uni COMPUTE_LOOP;
COMPUTE_DONE:
    bar.sync 0;
    add.s32 %r19, %r19, 1;   // kt++
    bra.uni KT_LOOP;
STORE_SUM:
    @%p7 st.global.f32 [%rd5], %f1;
    @%p9 st.global.f32 [%rd7], %f2;
    bra.uni DONE;
STORE_ZERO:
    mov.f32 %f10, 0f00000000;
    @%p7 st.global.f32 [%rd5], %f10;
    @%p9 st.global.f32 [%rd7], %f10;
DONE:
    ret;
}
"""
_ptx_module = None
def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module
